WITH valid AS (SELECT *, CAST(is_flagged AS INT) AS is_flagged_flag, CASE WHEN is_flagged THEN 'Yes' ELSE 'No' END AS is_flagged_label, COALESCE(merchant, 'DIRECT') AS resolved_merchant FROM transactions WHERE txn_time >= DATE '2023-07-29' AND amount BETWEEN 1800 AND 3900) SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, is_flagged_flag, is_flagged_label, resolved_merchant, LEAD(amount, 1) OVER (PARTITION BY merchant ORDER BY txn_time, id) AS next_amount, DENSE_RANK() OVER (PARTITION BY txn_type ORDER BY amount DESC) AS amount_dense_rank, CUME_DIST() OVER (PARTITION BY merchant ORDER BY is_flagged_flag DESC) AS is_flagged_flag_cume_dist, NTILE(5) OVER (PARTITION BY txn_type ORDER BY amount DESC, id) AS amount_bucket, LAST_VALUE(is_flagged_flag, TRUE) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_is_flagged_flag FROM valid
